#include <bits/stdc++.h>
using namespace std;

const int MOD_CONST = 998244353;
vector<long long> wTable, wTableRev;

long long fastPow(int base, int exp) {
    long long result = 1;
    long long baseLong = base;
    int e = exp;
    while (e > 0) {
        if (e & 1)
            result = (result * baseLong) % MOD_CONST;
        baseLong = (baseLong * baseLong) % MOD_CONST;
        e >>= 1;
    }
    return result;
}

void setup() {
    wTable.resize(21);
    wTableRev.resize(21);
    for (int h = 0; h <= 20; h++) {
        wTable[h] = fastPow(3, (MOD_CONST - 1) >> h);
        wTableRev[h] = fastPow(3, (MOD_CONST - 1) - ((MOD_CONST - 1) >> h));
    }
}

void performFFT(vector<long long>& data, int length, bool invert) {
    for (int i = 1, j = 0; i < length; i++) {
        int mask = length;
        do {
            j ^= mask >>= 1;
        } while ((j & mask) == 0);
        if (i < j) {
            swap(data[i], data[j]);
        }
    }
    for (int h = 0, size; (size = 1 << h) < length; h++) {
        long long wFactor = invert ? wTableRev[h + 1] : wTable[h + 1];
        for (int startIdx = 0; startIdx < length; startIdx += size * 2) {
            long long w = 1;
            for (int j = 0; j < size; j++) {
                int leftIdx = startIdx + j, rightIdx = leftIdx + size;
                long long u = data[leftIdx], v = data[rightIdx] * w % MOD_CONST;
                data[leftIdx] = (u + v) % MOD_CONST;
                data[rightIdx] = (u - v + MOD_CONST) % MOD_CONST;
                w = (w * wFactor) % MOD_CONST;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    setup();
    int nHalfVal, kCount;
    cin >> nHalfVal >> kCount;
    int sizeN = 1;
    while (sizeN < nHalfVal * 9 + 1)
        sizeN <<= 1;
    vector<long long> arrayData(sizeN, 0);
    for (int i = 0; i < kCount; i++) {
        int d;
        cin >> d;
        arrayData[d] = 1;
    }
    performFFT(arrayData, sizeN, false);
    for (int i = 0; i < sizeN; i++) {
        arrayData[i] = fastPow(arrayData[i], nHalfVal);
    }
    performFFT(arrayData, sizeN, true);
    long long invNVal = fastPow(sizeN, MOD_CONST - 2);
    long long totalSum = 0;
    for (int i = 0; i < sizeN; i++) {
        arrayData[i] = (arrayData[i] * invNVal) % MOD_CONST;
        totalSum = (totalSum + arrayData[i] * arrayData[i]) % MOD_CONST;
    }
    cout << totalSum << "\n";
    return 0;
}
